query:
-- Verificar a tag excluída
SELECT id, tag, HEX(tag) as hex_tag FROM equipamento_excluido_tag WHERE tag LIKE '%PERFURATRIZ%';

-- Verificar a tag nos itens importados
SELECT DISTINCT equipamentoTag, HEX(equipamentoTag) as hex_tag FROM item_despesa_importado WHERE equipamentoTag LIKE '%PERFURATRIZ HIDR%01%' LIMIT 3;

-- Verificar se existe correspondência aprovada ou forçada para esta tag
SELECT DISTINCT equipamentoTag, equipamentoSistemaId FROM item_despesa_importado WHERE equipamentoTag LIKE '%PERFURATRIZ HIDR%01%' LIMIT 3;

